/* Extends the established material/records panels with a persistent object world. */
'use strict';
const A=TownAdventure,CAT=TownCatalog,MC=MaterialCompiler,STORE=TownStorage;
const CAPACITY_SANDBOX=typeof location!=='undefined'&&new URLSearchParams(location.search).get('capacity')==='1000';
let selectedTool=null,selectedPiece=null,activeQuest=null,toolPage=0,showAllObjects=false,draggingObject=null,saveMeta=null,worldReady=false;
const originalRestore=L.restore;L.restore=raw=>{const s=originalRestore(raw);return s&&A.validate(s)?s:null;};
const oldMaterials=showMaterials,oldRecords=showRecords,oldReviewDraft=reviewDraft,oldViewCards=viewCards;
const sprites=(index,extra='')=>`<span class="prop-art ${extra}" style="--sheet:url('assets/world-props${index>=32?'3':index>=16?'2':''}.webp');--px:${index%4/3*100}%;--py:${Math.floor(index%16/4)/3*100}%"></span>`;
const toolArt=type=>sprites(A.types[type]?.[1]||0);
function quests(){return A.session(state).quests;}
function currentQuest(){const session=A.session(state),list=session.quests,remembered=Number.isInteger(session.active)?list[session.active]:null,q=list.find(q=>q.id===activeQuest)||(!remembered?.done?remembered:null)||list.find(q=>!q.done)||list[0];session.active=list.indexOf(q);return q;}
function zoneInfo(){return CAT.zones[state.zone]||CAT.zones.town;}
function stationFor(q){return zoneInfo().stations.find(x=>x[0]===q.station);}
function taskLocation(q,i){const z=zoneInfo(),safe=CAT.objects(state.zone).filter(o=>z.stations.every(st=>Math.abs(o.x-st[2])>5||Math.abs(o.y-st[3])>5)),seed=state.seed+run().number*919+quests().indexOf(q)*313+Object.keys(CAT.zones).indexOf(state.zone)*1777,list=A.shuffle(safe,seed);return list[i%list.length];}
function persist(){if(!worldReady||CAPACITY_SANDBOX)return;saveMeta=STORE.save(state);}
save=persist;
function capture(){A.init(state);A.session(state);save();}
renderHUD=function(){const p=A.progress(state),q=currentQuest(),st=stats(),a=A.init(state);if(selectedTool&&!a.inventory.some(x=>x.id===selectedTool.id))selectedTool=null;$('bankTitle').textContent=st.b.title;$('coins').textContent=state.resources.coins;$('paper').textContent=state.resources.paper;$('compassCount').textContent=state.resources.compass;$('questNumber').textContent=`第 ${run().number} 次寻知 · ${p.done}/${p.total} 份委托`;$('questTitle').textContent=run().finished?'这次整理完成，下一批知识正在等你。':q?.done?'这一份已归档，选择下一份委托。':q?.question||'带来材料，开始探索。';$('welcomeTip').hidden=!!state.guide;$('welcomeTip').innerHTML=`<span class="eyebrow">欢迎来到拾知小镇</span><strong>找得到，<br>也要用得上。</strong><p>找卷轴读材料，把它拖到书页或机器上。钥匙、壶、齿轮也能和场景里的物件组合。</p><div><button id="beginTown" class="primary">跟着引导玩一遍</button><button id="bringMaterial">导入学习材料</button></div>`;$('beginTown')?.addEventListener('click',startGuide);$('bringMaterial')?.addEventListener('click',importMaterial);for(const z of Object.keys(CAT.zones))$(z+'Button').classList.toggle('active',state.zone===z);$('sceneTip').textContent=selectedTool?'已选择「'+A.types[selectedTool.type][0]+'」· 点击场景装置使用 · 再点道具取消':selectedPiece?'已选择学习材料 · 点击对应装置投放 · Esc 取消':'拖动画面 · 滚轮/双指缩放 · 物品可拖到装置上';renderTray();save();};
function toolPageSize(){const width=window.innerWidth||$('viewport').clientWidth;return width<=360?2:width<=600?3:width<=900?4:width<=1100?5:8;}
function renderTray(){const p=A.progress(state),a=A.init(state),q=currentQuest(),pageSize=toolPageSize();toolPage=Math.min(toolPage,Math.max(0,Math.ceil(a.inventory.length/pageSize)-1));const items=a.inventory.slice(toolPage*pageSize,toolPage*pageSize+pageSize);$('adventureTray').innerHTML=`<div class="voyage-row"><button id="questList" class="voyage-summary"><span class="mini-label">本批学习委托</span><strong>${p.done}<small> / ${p.total}</small></strong><span class="voyage-bar"><i style="width:${p.done/p.total*100}%"></i></span></button><div class="quest-tabs">${quests().map((x,i)=>`<button data-quest="${x.id}" class="quest-tab ${x.id===q.id?'active':''} ${x.done?'complete':''}" title="${esc(x.question)}"><span>${x.done?'✓':i+1}</span><b>${esc(x.name)}</b><small>${x.done?'已归档':x.found.length+'/'+x.pieces.length+' 线索'}</small></button>`).join('')}</div><button id="nextVoyage" class="primary">${run().finished?'领取新委托':p.done===p.total?'完成整理 →':'查看当前任务 →'}</button></div><div class="inventory-row"><button id="inventoryGuide" class="inventory-label"><strong>道具与图鉴 ›</strong><small>${a.inventory.length} 件 · 本区 ${CAT.objects(state.zone).filter(o=>a.collected[o.id]).length}/${CAT.objects(state.zone).length}</small></button><button id="toolPrev" aria-label="上一页道具" ${toolPage?'':'disabled'}>‹</button><div class="tool-belt">${items.map(x=>`<button class="tool ${selectedTool?.id===x.id?'selected':''}" data-tool="${x.id}" draggable="true" title="${esc(A.types[x.type][0])}：拖到场景装置使用">${toolArt(x.type)}<small>${esc(A.types[x.type][0])}</small></button>`).join('')||'<span class="belt-empty">点击街角的小物件，把它们收进背包。先试着找一把铜钥匙。</span>'}</div><button id="toolNext" aria-label="下一页道具" ${(toolPage+1)*pageSize<a.inventory.length?'':'disabled'}>›</button><button id="learningBag" class="bag-tab">学习背包 <b>${q.found.filter(k=>!q.placed.includes(k)&&!q.rejected.includes(k)).length}</b></button><button id="worldBin" class="bin-target" data-drop="trash" aria-label="学习材料回收与道具暂存柜">回收柜</button></div>`;
$('questList').onclick=questDetail;$('nextVoyage').onclick=settle;$('learningBag').onclick=showBag;$('worldBin').onclick=()=>{if(selectedPiece)dropPiece('trash');else if(selectedTool)useTool('trash');else showRecycling();};$('toolPrev').onclick=()=>{toolPage--;renderTray();};$('toolNext').onclick=()=>{toolPage++;renderTray();};$('inventoryGuide').onclick=showRecipes;document.querySelectorAll('[data-quest]').forEach(el=>el.onclick=()=>{activeQuest=el.dataset.quest;selectedPiece=null;render();pointQuest();});document.querySelectorAll('[data-tool]').forEach(el=>{const item=a.inventory.find(x=>x.id===el.dataset.tool);el.onclick=()=>{selectedTool=selectedTool?.id===item.id?null:item;selectedPiece=null;renderHUD();highlightTargets();};bindDraggable(el,{tool:item.id});});bindDrop($('worldBin'),'trash');}
function objectButton(o){const p=A.init(state),done=p.collected[o.id];if(done)return'';return `<button class="world-object ${o.sprite?'has-sprite':'native-object'} ${showAllObjects?'reveal':''}" data-object="${o.id}" draggable="true" style="left:${o.x}%;top:${o.y}%;--tilt:${o.id.length%2?'-8':'7'}deg" aria-label="搜索${esc(o.name)}，可能找到${esc(A.types[o.type][0])}">${o.sprite?sprites(o.art??A.types[o.type][1]):'<span class="native-glint">✦</span>'}<span class="object-label">${esc(o.name)}</span></button>`;}
renderLoot=function(){const q=currentQuest(),p=A.init(state);$('features').innerHTML=CAT.objects(state.zone).map(objectButton).join('');$('loot').innerHTML=q.done?'':q.pieces.map((piece,i)=>{if(q.found.includes(piece.key))return'';const loc=taskLocation(q,i);return `<button class="learning-object ${showAllObjects?'reveal':''}" data-piece="${piece.key}" style="left:${loc.x}%;top:${loc.y}%;--delay:${i*.4}s" aria-label="查看藏在${esc(loc.name)}的学习材料">${sprites(q.mode==='order'?11:q.mode==='numeric'?9:0)}<span class="learning-spark">✦</span><span class="object-label">学习线索</span></button>`;}).join('');
$('stations').innerHTML=zoneInfo().stations.map((st,i)=>{const effect=Object.keys(p.effects).some(k=>k.startsWith(state.zone+'-'+st[0]+'|'));return `<button class="world-station ${st[0]===q.station&&!q.done?'quest-station':''} ${effect?'changed':''}" data-drop="${st[0]}" data-station="${st[0]}" style="left:${st[2]}%;top:${st[3]}%" aria-label="${esc(st[1])}，可放入道具或学习材料"><span class="station-symbol">${({book:'▥',mailbox:'✉',machine:'⚙',sorter:'▤',ledger:'◷',chest:'⌑',pot:'❀',bridge:'⌁',lamp:'✧',tea:'♧',map:'⌖',desk:'▧'})[st[0]]}</span><span>${esc(st[1])}${effect?' ✓':''}</span>${st[0]===q.station&&!q.done?'<b class="station-notice">本题装置</b>':''}</button>`;}).join('');
renderChanges();
document.querySelectorAll('[data-object]').forEach(el=>{const object=CAT.objects(state.zone).find(x=>x.id===el.dataset.object);bindDraggable(el,{world:object.id,type:object.type});el.onclick=e=>{if(Date.now()<suppressClick)return;e.stopPropagation();inspectObject(el.dataset.object);};});document.querySelectorAll('[data-piece]').forEach(el=>el.onclick=e=>{if(Date.now()<suppressClick)return;e.stopPropagation();inspectPiece(el.dataset.piece);});document.querySelectorAll('[data-station]').forEach(el=>{el.onclick=e=>{if(Date.now()<suppressClick)return;e.stopPropagation();const kind=el.dataset.station;if(selectedTool)useTool(kind);else if(selectedPiece)dropPiece(kind);else inspectStation(kind);};bindDrop(el,el.dataset.station);});highlightTargets();};
renderNPCs=function(){$('villagers').innerHTML=people.map((p,i)=>{const r=zoneInfo().routes[i];return `<button class="npc" data-npc="${i}" data-drop="${['book','mailbox','machine','pot'][i]}" style="left:${r[0]}%;top:${r[1]}%;--sx:${i/3*100}%;--dx:${r[2]}px;--dy:${r[3]}px;--duration:${17+i*4}s" aria-label="与${p.name}对话，${p.task}"><span class="npc-sprite"></span><span class="npc-label">${p.name}<small>${p.task}</small></span><span class="npc-notice">!</span></button>`;}).join('');document.querySelectorAll('[data-npc]').forEach(el=>{bindDrop(el,el.dataset.drop);el.onclick=e=>{if(Date.now()<suppressClick)return;e.stopPropagation();const i=+el.dataset.npc;if(selectedTool){const target=['book','mailbox','machine','pot'][i];useTool(target);return;}npc(i);};});};
render=function(){if($('fieldNote'))$('fieldNote').hidden=true;A.session(state);renderHUD();renderLoot();renderPlants();};
function renderAmbientScene(){
 if(typeof TownAmbient!=='undefined')TownAmbient.render(state.zone,$('world'),$('ambientScene'));
 if(typeof TownLandmarkMotion!=='undefined')TownLandmarkMotion.render(state.zone,$('world'));
}
renderWorld=function(){renderAmbientScene();const z=zoneInfo();$('worldArt').src=`assets/world-${state.zone}.webp`;$('worldArt').alt=z.name+'，可以拖动、放大并操作场景物件';renderNPCs();render();};
changeZone=function(zone){if(!CAT.zones[zone])return;close();state.zone=zone;clearTimeout(hintTimer);$('hintRing').hidden=true;renderWorld();resetCamera();save();toast('来到'+zoneInfo().name+'。知识委托、背包和成长记录继续累积。');};
function inspectObject(id){const o=CAT.objects(state.zone).find(x=>x.id===id);if(!o)return;const result=A.take(state,id,o.type);if(result.ok){state.guide=true;render();flash('找到 '+A.types[o.type][0]);}toast(result.message);save();}
function inspectPiece(key){state.guide=true;renderHUD();const q=currentQuest(),piece=q.pieces.find(x=>x.key===key);if(!piece)return;$('fieldNote').hidden=false;$('fieldNote').innerHTML=`<span class="eyebrow">${esc(q.name)} · 在${esc(taskLocation(q,q.pieces.indexOf(piece)).name)}发现</span><h2 id="fieldNoteTitle">${esc(q.question)}</h2><div class="candidate learning-candidate">${sprites(q.mode==='order'?11:0)}<span>${esc(piece.text)}</span></div><p>${esc(q.prompt)}</p><div class="actions"><button id="leavePiece">暂时留在这里</button><button id="takePiece" class="primary">收进学习背包</button></div><p class="muted">候选材料不一定正确。找到以后，仍要判断它能否回答这道问题。</p>`;$('leavePiece').onclick=()=>{$('fieldNote').hidden=true;};$('takePiece').focus();$('takePiece').onclick=()=>{const r=A.discover(state,q.id,key);close();selectedPiece={qid:q.id,key};selectedTool=null;render();toast(r.message);pointStation();if(state.play.tutorial===1){state.play.tutorial=2;guideSecond();}save();};}
function guideSecond(){modal(`<span class="eyebrow">第一次探索 · 2 / 3</span><h2 id="dialogTitle">找到以后，还要读懂怎么用。</h2><p>你刚找到的材料已放进学习背包。当前任务是「${esc(currentQuest().name)}」。</p><div class="note">${esc(currentQuest().prompt)}</div><p>点击下方按钮打开装置。先点选一份材料，再点目标框；也可以直接拖进去。不符合问题的材料放入回收框。</p><div class="actions"><button id="guideSecondGo" class="primary">打开装置，试着放一份材料</button></div>`);$('guideSecondGo').onclick=()=>openTask(currentQuest().id);}
function guideThird(){modal(`<span class="eyebrow">第一次探索 · 3 / 3</span><h2 id="dialogTitle">最后，核验并把知识留下来。</h2><p>放置成功了。剩下的候选材料还藏在街区，继续寻找，再把有效材料放齐、无关材料回收。</p><p>装置的「核验并归档」会检查完整情况。完成本批的所有委托，再领取下一批；小镇、材料和成长记录会一直保留。</p><div class="actions"><button id="guideThirdGo" class="primary">明白了，继续探索</button><button id="guideThirdTask">回到装置</button></div>`);$('guideThirdGo').onclick=()=>{close();render();pointQuest();};$('guideThirdTask').onclick=()=>openTask(currentQuest().id);}
function useTool(kind){const item=selectedTool;if(!item)return;const result=kind==='trash'?A.storeTool(state,item.id):A.combine(state,item.id,state.zone+'-'+kind,kind);if(result.ok){selectedTool=null;render();flash(result.message);animateEffect(kind);if(kind==='map')pointQuest();if(kind==='book'&&['lens','ink'].includes(item.type)){openTask(currentQuest().id);if($('sourcePanel'))$('sourcePanel').open=true;A.hint(state,currentQuest().id);}else if(kind==='book'&&item.type==='quill')manualCard();else if(kind==='desk'&&item.type==='notebook')importMaterial();toolPage=Math.min(toolPage,Math.max(0,Math.ceil(state.play.inventory.length/toolPageSize())-1));}toast(result.message);save();}
function dropPiece(kind,category){if(!selectedPiece)return;const{qid,key}=selectedPiece,q=A.task(state,qid);let result;if(kind==='trash')result=A.reject(state,qid,key);else if(kind!==q.station)result={ok:false,message:'这份材料属于「'+q.name+'」，请放到标注“本题装置”的位置。'};else if(['sort','pair','evidence'].includes(q.mode)&&category===undefined){openTask(qid);return;}else result=A.place(state,qid,key,category);if(result.ok){selectedPiece=null;render();flash(result.message);}toast(result.message);save();if(result.ready)openTask(qid);if(result.ok&&state.play.tutorial===2){state.play.tutorial=3;guideThird();save();}}
function inspectStation(kind){const q=currentQuest();if(q.station===kind&&!q.done){openTask(q.id);return;}const matching=Object.entries(A.recipes[kind]||{}).map(([k])=>A.types[k][0]);modal(`<span class="eyebrow">${esc(zoneInfo().name)} · 场景互动</span><h2 id="dialogTitle">${esc(zoneInfo().stations.find(x=>x[0]===kind)?.[1])}</h2><p>先在街区里找到道具，再从下方道具栏拖到这里。也可以先点选道具，再点击装置。</p><div class="recipe-hints">${matching.map(x=>`<span>${esc(x)}</span>`).join('')}</div><p class="muted">这些是这里可能接受的道具。每种组合只奖励一次；错放不会丢失物品。</p><div class="actions"><button id="stationBack" class="primary">回到场景试试</button><button id="stationRecipes">查看物品手册</button></div>`);$('stationBack').onclick=close;$('stationRecipes').onclick=showRecipes;}
function renderChanges(){const p=state.play,icons={chest:8,pot:p.effects[state.zone+'-pot|water']?21:4,mailbox:15,machine:11,ledger:9,book:3,bridge:10,lamp:13,tea:p.effects[state.zone+'-tea|flower']?21:26,map:24,desk:p.effects[state.zone+'-desk|notebook']?31:p.effects[state.zone+'-desk|coin']?30:14};$('persistentChanges').innerHTML=zoneInfo().stations.filter(st=>Object.keys(p.effects).some(k=>k.startsWith(state.zone+'-'+st[0]+'|'))).map(st=>`<div class="scene-change change-${st[0]}" style="left:${st[2]}%;top:${st[3]}%" aria-hidden="true">${sprites(icons[st[0]])}${st[0]==='pot'?'<i>❀</i>':st[0]==='lamp'?'<i>✧</i>':''}</div>`).join('');}
function animateEffect(kind){const st=zoneInfo().stations.find(x=>x[0]===kind);if(!st)return;$('sceneEffects').innerHTML=`<div class="effect-burst" style="left:${st[2]}%;top:${st[3]}%">${kind==='pot'?'❀':kind==='lamp'?'✧':'✦'}<i>✧</i><b>✦</b></div>`;setTimeout(()=>$('sceneEffects').innerHTML='',1800);}
function highlightTargets(){document.querySelectorAll('[data-station]').forEach(el=>el.classList.toggle('accepts-tool',!!selectedTool&&!!A.recipes[el.dataset.station]?.[selectedTool.type]));document.body.classList.toggle('holding-item',!!selectedTool||!!selectedPiece);}
function bindDrop(el,kind){el.ondragover=e=>{e.preventDefault();el.classList.add('dragover');};el.ondragleave=()=>el.classList.remove('dragover');el.ondrop=e=>{e.preventDefault();e.stopPropagation();el.classList.remove('dragover');let d;try{d=JSON.parse(e.dataTransfer.getData('application/x-town')||e.dataTransfer.getData('text/plain'));}catch{return;}applyDrag(d,kind,el.dataset.category===undefined?undefined:+el.dataset.category);};}
function applyDrag(data,kind,category){if(data.world){const object=CAT.objects(state.zone).find(x=>x.id===data.world);if(!object)return;const result=A.take(state,object.id,object.type);if(!result.ok){toast(result.message);return;}state.guide=true;selectedTool=state.play.inventory.find(x=>x.id===object.id);selectedPiece=null;useTool(kind);render();save();}else if(data.tool){selectedTool=state.play.inventory.find(x=>x.id===data.tool);selectedPiece=null;useTool(kind);}else if(data.qid){selectedPiece={qid:data.qid,key:data.key};selectedTool=null;dropPiece(kind,category);}}
function bindDraggable(el,data){el.ondragstart=e=>{e.stopPropagation();document.body.classList.add('dragging-prop');e.dataTransfer.setData('application/x-town',JSON.stringify(data));e.dataTransfer.setData('text/plain',JSON.stringify(data));e.dataTransfer.effectAllowed='move';};el.ondragend=()=>document.body.classList.remove('dragging-prop');el.addEventListener('pointerdown',e=>{e.stopPropagation();if(e.pointerType==='mouse')return;draggingObject={...data,pointer:e.pointerId,x:e.clientX,y:e.clientY,moved:false};el.setPointerCapture?.(e.pointerId);});el.addEventListener('pointermove',e=>{const d=draggingObject;if(!d||d.pointer!==e.pointerId)return;if(Math.hypot(e.clientX-d.x,e.clientY-d.y)>9)d.moved=true;if(d.moved){e.preventDefault();document.body.classList.add('dragging-prop');const g=$('dragGhost');g.textContent=data.tool||data.world?'✦':'卷';g.style.display='grid';g.style.left=e.clientX+'px';g.style.top=e.clientY+'px';}});el.addEventListener('pointerup',e=>{const d=draggingObject;if(!d)return;draggingObject=null;$('dragGhost').style.display='none';if(!d.moved){document.body.classList.remove('dragging-prop');return;}e.preventDefault();suppressClick=Date.now()+350;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');document.body.classList.remove('dragging-prop');if(target)applyDrag(d,target.dataset.drop,target.dataset.category===undefined?undefined:+target.dataset.category);else toast('松开的位置不是装置，物品仍在背包里。');});el.addEventListener('pointercancel',()=>{draggingObject=null;document.body.classList.remove('dragging-prop');$('dragGhost').style.display='none';});}
function pieceTokens(q){return q.pieces.filter(x=>q.found.includes(x.key)&&!q.placed.includes(x.key)&&!q.rejected.includes(x.key)).map(x=>`<button class="material-token ${selectedPiece?.qid===q.id&&selectedPiece.key===x.key?'selected':''}" draggable="true" data-material="${x.key}">${sprites(q.mode==='order'?11:0)}<span>${esc(x.text)}</span><small>拖入上方装置 · 或点选后点击目标</small></button>`).join('');}
function bindPieces(q){document.querySelectorAll('[data-material]').forEach(el=>{const key=el.dataset.material;bindDraggable(el,{qid:q.id,key});el.onclick=()=>{selectedPiece={qid:q.id,key};selectedTool=null;document.querySelectorAll('[data-material]').forEach(x=>x.classList.toggle('selected',x===el));$('taskMessage').textContent='已选择材料，点击上方目标放入；不符合的材料可点击回收框。';};});document.querySelectorAll('[data-taskdrop]').forEach(el=>{el.onclick=()=>{if(!selectedPiece){toast('先点选下方的一份材料。');return;}const r=el.dataset.taskdrop==='trash'?A.reject(state,q.id,selectedPiece.key):A.place(state,q.id,selectedPiece.key,el.dataset.category===undefined?undefined:+el.dataset.category);if(r.ok)selectedPiece=null;save();render();openTask(q.id,r.message);if(r.ok&&state.play.tutorial===2){state.play.tutorial=3;guideThird();save();}};bindDrop(el,el.dataset.taskdrop);});}
function openTask(qid,message=''){const q=A.task(state,qid);if(!q)return;activeQuest=qid;const needed=q.done?null:A.requirement(state,q);const destinations=['sort','pair','evidence'].includes(q.mode)?q.categories.map((label,i)=>`<button class="task-drop" data-taskdrop="${q.station}" data-drop="${q.station}" data-category="${i}"><strong>${esc(label)}</strong><span>${q.placed.filter(k=>q.pieces.find(x=>x.key===k)?.category===i).map(k=>esc(q.pieces.find(x=>x.key===k).text)).join('<br>')||(q.mode==='pair'?'把对应解释拖到这张概念卡':'把材料拖入这个分类')}</span></button>`).join(''):`<button class="task-drop main-taskdrop" data-taskdrop="${q.station}" data-drop="${q.station}"><strong>${q.mode==='order'?'装配槽 · 按先后顺序':'有效材料框'} ${q.placed.length}/${q.target}</strong><span>${q.placed.map(k=>esc(q.pieces.find(x=>x.key===k).text)).join(q.mode==='order'?' → ':'<br>')||'把下方候选材料拖进来'}</span></button>`;
modal(`<span class="eyebrow">${esc(q.name)} · ${esc(zoneInfo().name)}</span><h2 id="dialogTitle">${esc(q.question)}</h2><div class="task-prompt">${esc(q.prompt)}</div>${needed&&!needed.ready?`<div class="device-prerequisite"><strong>装置还未准备好</strong><p>先把${esc(A.types[needed.tool][0])}拖到${esc(zoneInfo().stations.find(x=>x[0]===needed.kind)?.[1])}，再回来核验材料。</p><button id="findDeviceTool">帮我找${esc(A.types[needed.tool][0])}</button></div>`:needed?'<div class="device-ready">✓ 实物装置已准备好</div>':''}${q.done?'<div class="feedback">这一份委托已经归档，之后可到邮差处独立复习。</div>':`<div class="task-destinations">${destinations}<button class="task-drop trash-drop" data-taskdrop="trash" data-drop="trash"><strong>本题无关材料</strong><span>已排除 ${q.rejected.length}/${q.pieces.filter(x=>!x.correct).length} 份</span></button></div><div id="taskMessage" class="task-message" role="status">${esc(message||'先读材料，再把它放到对应位置。')}</div><div class="material-grid">${pieceTokens(q)||'<div class="empty">背包里没有待处理材料。回到场景寻找卷轴、齿轮和小钟。</div>'}</div>`}<details class="source-detail" id="sourcePanel"><summary id="revealSource">查看原文依据与来源（辅助）</summary><div class="preview-source">${esc(q.quote||'本卡未提供原文，请回材料库核对。')}</div>${source(L.card(state,q.id))}</details><div class="actions"><button id="taskExplore">${q.done?(quests().some(x=>!x.done)?'去找下一份委托':'回到场景，结算本批'):'回场景找剩余材料'}</button><button id="checkTask" class="primary" ${q.done?'disabled':''}>核验并归档</button></div><p class="muted">这是有提示的即时练习，会记录接触与完成情况。长期复习级别由之后的独立答题积累。</p>`,true);if(!q.done)bindPieces(q);if($('findDeviceTool'))$('findDeviceTool').onclick=()=>locateTool(needed.tool,needed.kind);$('revealSource').onclick=()=>{A.hint(state,q.id);save();};$('taskExplore').onclick=()=>{if(q.done){const next=quests().find(x=>!x.done);if(next)activeQuest=next.id;}close();render();if(quests().every(x=>x.done)){$('nextVoyage').focus();toast('本批已全部归档，点击右下角“完成整理”领取本批奖励。');}else pointQuest();};if(q.mode==='roi'&&!q.done){const calc=document.createElement('div');calc.className='roi-calculator';calc.innerHTML=`<strong>收益算盘 · 自己算一遍</strong><p>ROI =（收益－成本）÷成本 × 100%</p><label>计算结果 <input id="roiValue" type="number" step="0.01" placeholder="例如 50 或 -25" value="${q.calculatedValue??''}"> %</label><button id="calculateROI" class="primary">拨动算盘核对</button><p id="roiFeedback" role="status"></p>`;$('dialogBody').appendChild(calc);$('calculateROI').onclick=()=>{const r=A.calculate(state,q.id,$('roiValue').value);$('roiFeedback').textContent=r.message;save();};}$('checkTask').onclick=()=>{const r=A.check(state,q.id,Date.now());save();render();openTask(q.id,r.message);if(r.ok){flash('知识归档 +1');toast(r.message);}};}
showBag=function(){openTask(currentQuest().id);};showArchive=showBag;
questDetail=function(){const p=A.progress(state);modal(`<span class="eyebrow">持续学习 · 第 ${run().number} 批</span><h2 id="dialogTitle">${esc(L.bank(state).title)}</h2><p>四个街区共享一份委托。完成这批后，优先安排到期复习与还没接触的知识；导入新材料时，原有积累继续保留。</p><div class="quest-list">${quests().map((q,i)=>`<button data-openquest="${q.id}"><span class="quest-index">${q.done?'✓':i+1}</span><span><b>${esc(q.question)}</b><small>${esc(q.name)} · ${q.done?'已归档':q.found.length+'/'+q.pieces.length+' 线索已找到'}</small></span><em>›</em></button>`).join('')}</div><p>本批已完成 ${p.done}/${p.total}；场景道具组合与学习任务分别记录。</p><div class="actions"><button id="questReturn">继续探索</button><button id="questMaterial">添加新材料</button></div>`);document.querySelectorAll('[data-openquest]').forEach(el=>el.onclick=()=>{activeQuest=el.dataset.openquest;close();render();pointQuest();});$('questReturn').onclick=close;$('questMaterial').onclick=importMaterial;};
settle=function(){if(run().finished){nextBatch();return;}const p=A.progress(state);if(p.done<p.total){showBag();return;}const result=L.finish(state,Date.now());if(!result){toast('这批记录还未完整，请查看委托清单。');return;}save();render();modal(`<span class="eyebrow">第 ${result.number} 批整理完成</span><h2 id="dialogTitle">把今天找到的知识，留给以后。</h2><div class="settle-seal">✓</div><p>完成 ${result.count} 份学习委托，获得 ${result.count} 枚学习币。你的材料、物品、花园与学习记录都已保存。</p><p>下一批继续安排新内容与到期复习，不需要从第一个场景重玩。也可以导入下一门课程，继续同一个小镇。</p><div class="actions"><button id="settleAlbum">查看这次的纪念章</button><button id="newMaterials">换一份学习材料</button><button id="newVoyage" class="primary">领取下一批委托</button></div>`);$('settleAlbum').onclick=()=>showAlbum();$('newMaterials').onclick=importMaterial;$('newVoyage').onclick=nextBatch;};
nextBatch=function(){close();L.start(state,Date.now(),true);activeQuest=null;selectedPiece=null;A.session(state);render();save();toast('新一批材料已藏进街区，探索与成长继续累积。');};
function showRecycling(){const q=currentQuest();modal(`<span class="eyebrow">材料回收</span><h2 id="dialogTitle">有用的留下，暂存的还能取回。</h2><p>学习材料需要先对照当前问题判断。误判有效材料时不会删除它；已排除的无关材料会留下再生纸。</p><div class="scroll-list">${q.rejected.map(k=>`<div class="item-row">${esc(q.pieces.find(x=>x.key===k).text)}</div>`).join('')||'<div class="empty">这一题还没有回收记录。</div>'}</div><div class="stored-tools">${state.play.storage.map(x=>`<button data-retrieve="${esc(x.id)}">${toolArt(x.type)}<span>${esc(A.types[x.type][0])}</span><small>取回道具</small></button>`).join('')}</div><div class="actions"><button id="recycleTask" class="primary">整理当前题的材料</button><button id="recycleCraft">用纸合成罗盘</button></div>`);document.querySelectorAll('[data-retrieve]').forEach(el=>el.onclick=()=>{const r=A.retrieve(state,el.dataset.retrieve);save();render();showRecycling();toast(r.message);});$('recycleTask').onclick=showBag;$('recycleCraft').onclick=showCraft;}
function locateTool(type,kind){close();let item=state.play.inventory.find(x=>x.type===type);if(!item){const stored=state.play.storage.find(x=>x.type===type);if(stored){const recovered=A.retrieve(state,stored.id);if(!recovered.ok){showRecycling();toast(recovered.message);return;}item=state.play.inventory.find(x=>x.id===stored.id);}}if(item){selectedTool=item;selectedPiece=null;render();const st=zoneInfo().stations.find(x=>x[0]===kind);pointXY(st[2],st[3]);toast('已选择'+A.types[type][0]+'，把它拖到指引圈里的装置上。');save();return;}const object=CAT.objects(state.zone).find(x=>x.type===type&&!state.play.collected[x.id]);if(object){pointXY(object.x,object.y);toast('这里藏着'+A.types[type][0]+'。先收集，再拖到装置。');}else toast('这个街区的道具已取走，可以去其他街区找同类道具，或查看暂存柜。');}
function showExplorationAlbum(){const p=A.init(state),all=Object.keys(CAT.zones).flatMap(z=>CAT.objects(z).map(o=>({...o,zone:z}))),found=all.filter(o=>p.collected[o.id]),seen=new Set(found.map(o=>o.type));modal(`<span class="eyebrow">拾知小镇 · 探索图鉴</span><h2 id="dialogTitle">每个街角，都留下发现。</h2><div class="album-intro"><strong>${found.length}<small> / ${all.length} 处藏物</small></strong><span>发现 ${seen.size} / ${Object.keys(A.types).length} 类道具。使用后仍会留在图鉴里；学习线索另行记录，不混进藏物数量。</span></div><div class="district-discoveries">${Object.entries(CAT.zones).map(([z,info])=>{const objects=CAT.objects(z),n=objects.filter(o=>p.collected[o.id]).length;return `<button data-catalogzone="${z}"><strong>${esc(info.name)}</strong><span>${n} / ${objects.length}</span><i style="--progress:${n/objects.length*100}%"></i></button>`;}).join('')}</div><div class="discovery-grid">${Object.entries(A.types).map(([type,v])=>{const count=found.filter(o=>o.type===type).length,total=all.filter(o=>o.type===type).length;return `<button data-catalogtype="${type}" class="${count?'discovered':'undiscovered'}" aria-label="寻找${esc(v[0])}">${toolArt(type)}<strong>${esc(v[0])}</strong><small>${count} / ${total} 已发现</small><span>${count===total?'这一类已找齐':'去找下一件 →'}</span></button>`;}).join('')}</div><p class="muted">这里记录固定街区的探索收集。学习委托会随你的材料持续生成；每批线索位置会变化，完成记录和主题徽章持续保留。</p><div class="actions"><button id="catalogLearning">查看学习纪念册</button><button id="catalogBack" class="primary">回到街区</button></div>`,true);document.querySelectorAll('[data-catalogzone]').forEach(el=>el.onclick=()=>{changeZone(el.dataset.catalogzone);});document.querySelectorAll('[data-catalogtype]').forEach(el=>el.onclick=()=>{const type=el.dataset.catalogtype,target=all.find(o=>o.zone===state.zone&&o.type===type&&!p.collected[o.id])||all.find(o=>o.type===type&&!p.collected[o.id]);if(!target){toast('这类道具已经找齐，去看看别的街角吧。');return;}close();if(target.zone!==state.zone)changeZone(target.zone);pointXY(target.x,target.y);toast('已经带你来到可能藏着「'+A.types[type][0]+'」的街角，点击小物件搜索。');});$('catalogLearning').onclick=()=>showAlbum();$('catalogBack').onclick=close;}
function showRecipes(){modal(`<span class="eyebrow">小镇物品手册</span><h2 id="dialogTitle">物品会改变身边的场景。</h2><div class="recipe-list">${Object.entries(A.recipes).map(([kind,items])=>`<div><strong>${esc(zoneInfo().stations.find(x=>x[0]===kind)?.[1])}</strong><span>${Object.keys(items).map(type=>`<span class="recipe-item">${toolArt(type)}${esc(A.types[type][0])}</span>`).join('')}</span></div>`).join('')}</div><p>先点击街区物件收集道具。拖到目标上使用，也可以“点道具 → 点装置”。每个装置与道具的组合只结算一次，错误组合保留物品。</p><p>累计发现 ${state.play.discoveries} 次，成功组合 ${state.play.combinations} 次。</p><div class="actions"><button id="recipeBack" class="primary">回到场景试试</button><button id="explorationAlbum">打开探索图鉴</button><button id="tidyTools">整理道具，同类暂存</button><button id="highlightObjects">暂时标出可搜索物件</button><button id="toggleCoupled">${state.play.coupled?'切换为快速学习':'开启实物装置探索'}</button></div>`);$('explorationAlbum').onclick=showExplorationAlbum;$('tidyTools').onclick=()=>{const moved=A.organize(state);render();save();showRecipes();toast(moved?'已暂存 '+moved+' 件重复同类道具，可随时到回收柜取回。':'随身道具没有重复同类，不需要整理。');};$('toggleCoupled').onclick=()=>{state.play.coupled=!state.play.coupled;save();render();showRecipes();toast(state.play.coupled?'探索模式：流程机器需要齿轮，计算账本需要闹钟。':'快速学习模式：保留找材料与解题，暂时跳过实物装置准备。');};$('recipeBack').onclick=close;$('highlightObjects').onclick=()=>{close();showAllObjects=true;renderLoot();setTimeout(()=>{showAllObjects=false;renderLoot();},12000);};}
function pointStation(){const st=stationFor(currentQuest());if(st)pointXY(st[2],st[3]);}
function pointXY(x,y){const ring=$('hintRing');clearTimeout(hintTimer);ring.hidden=false;ring.style.left=x+'%';ring.style.top=y+'%';zoomAt(Math.max(Math.min(4,.85/cameraBase()),camera.z));const scale=cameraBase()*camera.z;camera.x=$('viewport').clientWidth/2-x/100*W*scale;camera.y=$('viewport').clientHeight/2-y/100*H*scale;applyCamera();hintTimer=setTimeout(()=>ring.hidden=true,6500);}
function pointQuest(){const q=currentQuest(),i=q.pieces.findIndex(x=>!q.found.includes(x.key));if(i>=0){const loc=taskLocation(q,i);pointXY(loc.x,loc.y);}else pointStation();}
startGuide=function(){const pending=quests().find(q=>!q.done&&q.pieces.some(p=>!q.found.includes(p.key)));if(!pending){questDetail();toast('本批材料已找齐。整理并领取新委托后，可以重新体验首次引导。');return;}activeQuest=pending.id;state.guide=true;state.play.tutorial=1;render();modal(`<span class="eyebrow">第一次探索 · 1 / 3</span><h2 id="dialogTitle">先找一份藏起来的材料。</h2><div class="guide-illustration">${sprites(0)}<span>→</span>${sprites(1)}</div><p>接下来镜头会靠近第一份卷轴。点击卷轴，读里面的候选答案，收进学习背包。</p><div class="note">找到不等于答对。候选材料有真有假，之后要自己判断。</div><div class="actions"><button id="guideFirst" class="primary">带我去找第一份卷轴</button></div>`);$('guideFirst').onclick=()=>{close();pointQuest();toast('点击发光圈附近的卷轴，读材料并收进学习背包。');};save();};
help=function(){modal(`<span class="eyebrow">拾知小镇 · 探索手册</span><h2 id="dialogTitle">先发现，再理解，最后让知识留下来。</h2><div class="how-grid"><div><b>01 · 找材料</b><p>拖动场景、滚轮或双指缩放。当前题的卷轴会藏在桌面、货架和街角，点击后收进学习背包。</p></div><div><b>02 · 动手解题</b><p>把候选材料拖到标注“本题装置”的位置，或先点选再点击装置。流程按顺序装配，分类放到对应格，无关材料放回收框。</p></div><div><b>03 · 收集与组合</b><p>钥匙、壶、木板和齿轮在随身道具栏。拖到宝箱、花盆、桥和机器，看看场景会发生什么。</p></div><div><b>04 · 持续积累</b><p>归档后领取下一批；导入新课程沿用同一座小镇。邮差负责独立复习，园丁照料绑定学习材料的植物。</p></div></div><p>Esc 取消选中的物品。键盘 Tab 可选物件，Enter 触发；画面获得焦点后，方向键移动，＋/− 缩放，0 回全景。</p><div class="actions"><button id="helpGo" class="primary">继续探索</button><button id="helpGuide">重看第一次引导</button><button id="helpRecipes">物品手册</button></div>`);$('helpGo').onclick=close;$('helpGuide').onclick=startGuide;$('helpRecipes').onclick=showRecipes;};
showMaterials=function(){oldMaterials();const b=document.createElement('div');b.className='capacity-inline';const total=state.banks.reduce((n,x)=>n+x.cards.length,0);b.innerHTML=`<strong>实际保存 ${total.toLocaleString('zh-CN')} 道题</strong><span>1000 题容量已有合成测试记录，真实材料仍需你核对内容。</span><button id="capacityDetails">查看容量与测试</button><button id="structuredTemplate">下载多玩法材料模板</button><button id="pairSample">试试概念配对</button>`;$('dialogBody').appendChild(b);$('capacityDetails').onclick=showCapacity;$('structuredTemplate').onclick=downloadTemplate;$('pairSample').onclick=()=>{let b=state.banks.find(b=>b.id==='demo-pairs');if(!b){if(state.banks.length>=100||state.banks.reduce((n,b)=>n+b.cards.length,0)>=10000){toast('材料库已达到保护上限，请先导出并整理已有材料。');return;}b=L.addBank(state,{title:'AI 商业 · 概念配对示例',kind:'原创互动示例',cards:[P.card(pairSample,'原创配对教学示例',0)]},Date.now());const old=b.id;b.id='demo-pairs';b.cards.forEach(c=>c.id=c.id.replace(old,b.id));}state.selected=b.id;activeQuest=null;selectedPiece=null;close();L.start(state,Date.now());render();pointQuest();save();toast('找到解释材料，再把它们配到对应的概念卡上。');};};
viewCards=function(page=0,query='',filter='all'){if(typeof page!=='number')page=0;const b=L.bank(state),needle=query.trim().toLocaleLowerCase('zh-CN'),cards=b.cards.filter(c=>(!needle||[c.q,c.a,c.quote,c.topic,c.locator].some(x=>String(x||'').toLocaleLowerCase('zh-CN').includes(needle)))&&(filter==='all'||filter==='unseen'&&!state.progress[c.id]?.seen||filter==='due'&&state.progress[c.id]?.attempts&&state.progress[c.id].due<=Date.now())),size=25,totalPages=Math.max(1,Math.ceil(cards.length/size));page=Math.max(0,Math.min(page,totalPages-1));modal(`<span class="eyebrow">材料库 · 全量检索与来源</span><h2 id="dialogTitle">${esc(b.title)}</h2><div class="card-search"><input id="cardQuery" value="${esc(query)}" aria-label="检索问题、答案、原文或主题" placeholder="搜索问题、答案、原文或主题"><select id="cardFilter" aria-label="按学习状态筛选"><option value="all" ${filter==='all'?'selected':''}>全部题目</option><option value="unseen" ${filter==='unseen'?'selected':''}>尚未接触</option><option value="due" ${filter==='due'?'selected':''}>到期复习</option></select><button id="searchCards">搜索</button></div><p class="muted">材料共有 ${b.cards.length} 题；当前找到 ${cards.length} 题。每页 ${size} 题，可以一直翻到最后一题。</p><div class="scroll-list">${cards.slice(page*size,(page+1)*size).map(c=>`<div class="item-row"><strong>${esc(c.q)}</strong><p>${esc(c.a)}</p><small>可编排：${MC.available(c).map(k=>MC.names[k]).join(' · ')} · 复习级别 ${state.progress[c.id]?.level||0}/5</small><details><summary>原文、位置与玩法结构</summary><div class="preview-source">${esc(c.quote)}</div>${source(c)}${c.steps?'<p>流程：'+c.steps.map(esc).join(' → ')+'</p>':''}${c.answers?'<p>正确项：'+c.answers.map(esc).join('；')+'</p>':''}${c.pairs?'<p>配对：'+c.pairs.map(p=>esc(p.left)+' ↔ '+esc(p.right)).join('；')+'</p>':''}${c.categories?'<p>'+c.categories.map(x=>esc(x.label)+'：'+x.items.map(esc).join('、')).join('<br>')+'</p>':''}</details></div>`).join('')||'<div class="empty">没有匹配的题目，换个词或筛选条件试试。</div>'}</div><div class="pagination"><button id="cardsPrev" ${page?'':'disabled'}>上一页</button><span>第 ${page+1} / ${totalPages} 页</span><button id="cardsNext" ${page+1<totalPages?'':'disabled'}>下一页</button></div><div class="actions"><button id="cardsBack">返回材料库</button><button id="exportCards">导出这份材料</button></div>`,true);$('cardsPrev').onclick=()=>viewCards(page-1,query,filter);$('cardsNext').onclick=()=>viewCards(page+1,query,filter);const search=()=>viewCards(0,$('cardQuery').value,$('cardFilter').value||'all');$('searchCards').onclick=search;$('cardQuery').onkeydown=e=>{if(e.key==='Enter')search();};$('cardFilter').onchange=search;$('cardsBack').onclick=showMaterials;$('exportCards').onclick=()=>download(b.title.replace(/[\\/:*?"<>|]/g,'_')+'.json',JSON.stringify({title:b.title,cards:b.cards},null,2));};
reviewDraft=function(){oldReviewDraft();document.querySelectorAll('[data-draft]').forEach(el=>{const i=+el.dataset.draft,c=draft.cards[i],p=MC.preview(c),info=document.createElement('div');info.className='compiler-preview';info.innerHTML=`<b>会生成：${esc(p.label)}</b><span>${p.available.map(x=>x.label).join(' · ')}</span>${p.warnings.map(x=>`<small>${esc(x)}</small>`).join('')}<button data-editstructure="${i}">编辑玩法结构</button>`;el.appendChild(info);});document.querySelectorAll('[data-editstructure]').forEach(el=>el.onclick=()=>{syncDraft();editStructure(+el.dataset.editstructure);});};
function editStructure(index){
 const c=draft.cards[index],fields=['mode','steps','answers','pairs','categories','context','blank','calculation'],value=Object.fromEntries(fields.filter(k=>c[k]!==undefined).map(k=>[k,c[k]])),initial=c.mode||MC.choose(c);
 modal(`<span class="eyebrow">第 ${index+1} 题 · 调整互动方式</span><h2 id="dialogTitle">${esc(c.q)}</h2><p>按照材料本来的结构选择玩法，不需要为了凑玩法改写知识。</p><label class="form-label" for="structureMode">这道题适合怎样互动？</label><select id="structureMode" class="structure-mode">${Object.entries(MC.names).map(([id,label])=>`<option value="${id}" ${id===initial?'selected':''}>${label}</option>`).join('')}</select><div id="structureForm" class="structure-form"></div><details class="advanced-structure"><summary>高级：直接编辑结构数据</summary><label class="form-label"><input type="checkbox" id="useRawStructure"> 使用下面的 JSON 代替表单</label><textarea id="structureJson" class="code-editor" aria-label="高级结构 JSON">${esc(JSON.stringify(value,null,2))}</textarea></details><div id="structureFeedback" class="feedback" role="status"></div><div class="actions"><button id="structureCancel">返回核对题目</button><button id="structureSave" class="primary">保留这种玩法</button></div>`);
 $('structureMode').value=initial;
 function draw(){const mode=$('structureMode').value;let html='';if(mode==='evidence')html=`<label class="form-label" for="structureLines">第一行填写合适行动，第二行填写支持它的依据</label><textarea id="structureLines">${esc((c.answers||[]).join('\n'))}</textarea><label class="form-label" for="structureContext">业务情境</label><textarea id="structureContext">${esc(c.context||c.q)}</textarea><p class="muted">正好两行；无关候选在上一页填写，并请核对原文依据。</p>`;else if(mode==='roi')html=`<label>同一期间完整成本<input id="roiCost" type="number" min="0.01" step="any" value="${c.calculation?.costs??''}"></label><label>同一期间收益<input id="roiBenefit" type="number" min="0" step="any" value="${c.calculation?.benefits??''}"></label><p class="muted">金额使用相同单位。ROI =（收益－成本）÷成本×100%。正确答案也要在上一页核对。</p>`;else if(mode==='order')html=`<label class="form-label" for="structureLines">按正确顺序填写步骤，每行一步</label><textarea id="structureLines" placeholder="明确问题\n记录基线\n小范围验证">${esc((c.steps||[]).join('\n'))}</textarea><p class="muted">需要2至8个能够区分的步骤，顺序必须有原文依据。</p>`;else if(mode==='multi')html=`<label class="form-label" for="structureLines">每行填写一个正确项</label><textarea id="structureLines">${esc((c.answers||[]).join('\n'))}</textarea><p class="muted">至少两个正确项。错误候选仍在上一页的“错误选项”中填写。</p>`;else if(mode==='pair')html=`<label class="form-label" for="structureLines">每行一组：概念 = 对应解释或用途</label><textarea id="structureLines" placeholder="检索资料 = 找到相关原文片段&#10;人工复核 = 核对事实和适用条件">${esc((c.pairs||[]).map(p=>p.left+' = '+p.right).join('\n'))}</textarea><p class="muted">需要2至6组；每个概念和对应材料都要能清楚区分，并有原文依据。</p>`;else if(mode==='sort')html=`<label class="form-label" for="structureLines">每行一个分类，冒号后填写条目，用 | 分隔</label><textarea id="structureLines" placeholder="效率指标：完成用时 | 返工时长\n质量指标：错误率 | 合格率">${esc((c.categories||[]).map(x=>x.label+'：'+x.items.join(' | ')).join('\n'))}</textarea><p class="muted">需要2至4类；同一条目不能同时属于两类。</p>`;else if(mode==='scenario')html=`<label class="form-label" for="structureContext">玩家遇到了什么情境？</label><textarea id="structureContext" placeholder="写明实际情境、限制和要做的决定">${esc(c.context||'')}</textarea><p class="muted">正确处理建议与错误候选在上一页核对。</p>`;else if(mode==='cloze')html=`<label class="form-label" for="structureBlank">把答案的位置写成 ___</label><textarea id="structureBlank" placeholder="用于回答问题的资料，需要保留___。">${esc(c.blank||c.quote.replace(c.a,'___'))}</textarea><p class="muted">空格应与上一页填写的正确答案对应。</p>`;else if(mode==='numeric'){const p=c.calculation||{};html=`<div class="numeric-structure">${[['before','原先用时'],['after','生成耗时'],['review','复核耗时']].map(([key,label])=>`<label>${label}<input id="calc${key}" type="number" min="0" max="100000" step="any" value="${p[key]??''}"></label>`).join('')}<label>时间单位<input id="calcunit" value="${esc(p.unit||'分钟')}"></label></div><p class="muted">净节省＝原先用时－生成耗时－复核耗时。上一页的答案和单位也要一致。</p>`;}else html='<div class="note">这种玩法直接使用已核对的问题、答案与错误候选，不需要额外结构。</div>';$('structureForm').innerHTML=html;}
 draw();$('structureMode').onchange=draw;$('useRawStructure').onchange=()=>{$('structureForm').classList.toggle('inactive',$('useRawStructure').checked);};$('structureCancel').onclick=reviewDraft;
 $('structureSave').onclick=()=>{try{let raw;if($('useRawStructure').checked){try{raw=JSON.parse($('structureJson').value||'{}');}catch{throw Error('结构数据格式有误，请检查括号、逗号和引号，或取消高级模式后使用表单。');}}else{const mode=$('structureMode').value;raw={mode};const lines=()=>($('structureLines')?.value||'').split('\n').map(x=>x.trim()).filter(Boolean);if(mode==='evidence'){raw.answers=lines();raw.context=$('structureContext').value.trim();if(raw.answers.length!==2)throw Error('请填写恰好两行：行动和依据。');}if(mode==='roi'){if(!$('roiCost').value.trim()||!$('roiBenefit').value.trim())throw Error('请填写完整成本和同期间收益。');raw.calculation={operation:'roi',costs:Number($('roiCost').value),benefits:Number($('roiBenefit').value),unit:'%'};}if(mode==='order')raw.steps=lines();if(mode==='multi')raw.answers=lines();if(mode==='pair')raw.pairs=lines().map(line=>{const split=line.search(/[=＝]/);return{left:split<0?'':line.slice(0,split).trim(),right:split<0?'':line.slice(split+1).trim()};});if(mode==='sort')raw.categories=lines().map(line=>{const split=line.search(/[:：]/);return{label:split<0?'':line.slice(0,split).trim(),items:split<0?[]:line.slice(split+1).split('|').map(x=>x.trim()).filter(Boolean)};});if(mode==='scenario')raw.context=$('structureContext').value.trim();if(mode==='cloze')raw.blank=$('structureBlank').value.trim();if(mode==='numeric'&&['before','after','review'].some(k=>!$('calc'+k).value.trim()))throw Error('请填写原先用时、生成耗时和复核耗时，零也需要明确填写。');if(mode==='numeric')raw.calculation={operation:'net-time',before:Number($('calcbefore').value),after:Number($('calcafter').value),review:Number($('calcreview').value),unit:$('calcunit').value.trim()||'分钟'};}
 if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('玩法结构应为有效对象。');const candidate={...c};fields.forEach(k=>delete candidate[k]);const normalized=P.card({...candidate,...raw},c.source,index),preview=MC.preview(normalized);if(raw.mode&&!MC.available(normalized).includes(raw.mode))throw Error('当前填写的内容还不足以生成这种玩法，请按上方说明补齐步骤、分类或情境。');if(raw.mode==='roi'){const value=Math.round((normalized.calculation.benefits-normalized.calculation.costs)/normalized.calculation.costs*10000)/100;if(Number(String(normalized.a).replace(/[%％\s]/g,''))!==value)throw Error('答案与ROI计算不一致，请先返回上一页核对答案。');}const conflict=preview.warnings.find(x=>x.includes('计算结构与答案不一致'));if(conflict)throw Error(conflict);for(const k of fields){delete c[k];if(normalized[k]!==undefined)c[k]=normalized[k];}reviewDraft();toast('玩法已保留，加入前仍需核对答案与原文。');}catch(error){$('structureFeedback').textContent=error.message||'请检查填写的玩法结构。';}};
}
showRecords=function(){oldRecords();const extra=document.createElement('div');extra.className='capacity-inline';extra.innerHTML=`<strong>探索足迹：${state.play.discoveries} 次发现 · ${state.play.combinations} 次组合</strong><p>${state.play.journal.slice(-5).reverse().map(x=>esc(x.text)).join('<br>')||'还没有完成的场景组合，试试把钥匙拖到宝箱上。'}</p><button id="recordAlbum">打开学习纪念册</button><button id="recordCapacity">查看容量与保存状态</button>`;$('dialogBody').appendChild(extra);$('recordAlbum').onclick=()=>showAlbum();$('recordCapacity').onclick=showCapacity;};
function showAlbum(page=0){if(typeof page!=='number')page=0;const entries=[...state.history].reverse(),size=9,pages=Math.max(1,Math.ceil(entries.length/size));page=Math.max(0,Math.min(page,pages-1));const themes=state.banks.filter(b=>b.keepsake),date=at=>Number.isFinite(at)?new Date(at).toLocaleDateString('zh-CN',{year:'numeric',month:'short',day:'numeric'}):'历史记录';modal(`<span class="eyebrow">拾知小镇 · 学习纪念册</span><h2 id="dialogTitle">走过的街角，读懂的材料。</h2><div class="album-intro"><strong>${state.completed}<small> 次整理</small></strong><span>每完成一批，留下一枚纪念章。每份材料的主题徽章会一直保留。</span></div>${themes.length?`<div class="theme-keepsakes">${themes.map(b=>`<div><span class="theme-seal">知</span><strong>${esc(b.title)}</strong><small>${esc(date(b.keepsake.at))} · 获得主题徽章</small></div>`).join('')}</div>`:''}<div class="album-grid">${entries.slice(page*size,(page+1)*size).map(h=>{const z=Object.hasOwn(CAT.zones,h.zone)?h.zone:'town',title=h.bankTitle||state.banks.find(b=>b.id===h.bank)?.title||'过去的学习材料';return `<article class="memory-stamp"><div class="stamp-landscape" style="background-image:url('assets/world-${z}.webp')"><span class="postmark">拾知<br>第 ${esc(h.number)} 枚</span></div><div class="stamp-caption"><small>${esc(CAT.zones[z].name)} · ${esc(date(h.at))}</small><h3>${esc(title)}</h3><p>整理 ${esc(h.count)} 份知识 · ${h.mistakes?'认真修正了 '+esc(h.mistakes)+' 次':'这次判断很稳'}</p></div></article>`;}).join('')||'<div class="empty">第一枚纪念章还在路上。完成本批委托后，就能把今天的探索收进来。</div>'}</div><div class="pagination"><button id="albumPrev" ${page?'':'disabled'}>上一页</button><span>第 ${page+1}/${pages} 页</span><button id="albumNext" ${page+1<pages?'':'disabled'}>下一页</button></div><p class="muted">这里翻看最近300批记录；累计整理次数持续保留，主题徽章不随最近记录翻页而消失。纪念章记录完成经历，不代表考试能力认证。</p><div class="actions"><button id="albumBack">回成长手记</button><button id="albumGarden">看看记忆花园</button><button id="albumExploration">探索物品图鉴</button><button id="albumContinue" class="primary">继续探索</button></div>`,true);$('albumPrev').onclick=()=>showAlbum(page-1);$('albumNext').onclick=()=>showAlbum(page+1);$('albumBack').onclick=showRecords;$('albumGarden').onclick=showGarden;$('albumExploration').onclick=showExplorationAlbum;$('albumContinue').onclick=close;}
function showCapacity(){const total=state.banks.reduce((n,b)=>n+b.cards.length,0),bytes=new Blob([JSON.stringify(state)]).size;modal(`<span class="eyebrow">容量与保存 · 可以核对的数字</span><h2 id="dialogTitle">现在真正存了多少，而非只看上限。</h2><div class="stats-grid"><div class="stat-box"><strong>${total.toLocaleString('zh-CN')}</strong><small>本机实际题目</small></div><div class="stat-box"><strong>${(bytes/1024).toFixed(1)} KB</strong><small>当前完整存档体积</small></div><div class="stat-box"><strong>${state.banks.length}</strong><small>学习材料</small></div><div class="stat-box"><strong>${STORE.status().backend}</strong><small>当前保存方式</small></div></div><p><a class="sandbox-link" href="?capacity=1000" target="_blank" rel="noopener">打开独立的 1000 题试玩区 ↗</a></p><div id="capacityReport" class="note">正在读取本版本的容量测试结果…</div><p>测试使用明确标记的合成材料，检查导入、编排、遍历、归档与备份恢复。它验证数据流程，不证明所有手机或任意长度材料都能达到相同性能。</p><p class="muted">每次导入最多 2000 题、2 MB 文本；本机有 10000 题保护阈值。这个阈值是防止异常导入的限制，不代表已经验证 10000 题运行性能。</p><div class="actions"><button id="capacityBack">返回材料库</button><button id="exportCapacityBackup" class="primary">导出当前完整备份</button></div>`);$('capacityBack').onclick=showMaterials;$('exportCapacityBackup').onclick=()=>download('拾知小镇备份_'+L.day(Date.now())+'.json',JSON.stringify(state,null,2));fetch('capacity-report.json').then(r=>r.ok?r.json():Promise.reject()).then(r=>{if(!$('capacityReport'))return;$('capacityReport').textContent=`本版本测试：${r.questions} 道合成题；${r.quests} 份任务编排；${r.archived} 道题完成归档；备份恢复 ${r.restored?'通过':'未通过'}。测试环境 ${r.environment}，总耗时 ${r.elapsedMs} ms，存档 ${(r.bytes/1024).toFixed(1)} KB。`;}).catch(()=>{if($('capacityReport'))$('capacityReport').textContent='测试报告暂时无法读取，请刷新后重试；当前实际题目数与存档体积不受影响。';});}
function downloadTemplate(){download('多玩法材料模板.json',JSON.stringify({title:'我的多玩法学习材料',cards:[...advancedSamples,pairSample]},null,2));}
