$('fullscreen').onclick=async()=>{if(document.fullscreenElement){await document.exitFullscreen();return;}if(document.body.classList.contains('town-immersive')){document.body.classList.remove('town-immersive');$('fullscreen').textContent='沉浸';resetCamera();return;}document.body.classList.add('town-immersive');$('fullscreen').textContent='退出';try{if(document.documentElement?.requestFullscreen)await document.documentElement.requestFullscreen();}catch{}resetCamera();};document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){document.body.classList.remove('town-immersive');$('fullscreen').textContent='沉浸';}resetCamera();});
